class TestDynamicRendering:
    """Validates actual DOM rendering using jsdom + React."""

    @pytest.mark.skipif(
        not node_available(),
        reason="Node.js not available for dynamic tests",
    )
    def test_renders_all_nav_items(self, sidebar_source: str):
        """The component must render all expected nav items."""
        script = """
        const React = require('react');
        const { render, screen } = require('@testing-library/react');
        const { MemoryRouter } = require('react-router-dom');
        const Sidebar = require('./src/components/Sidebar').default;

        const { container } = render(
            React.createElement(MemoryRouter, null,
                React.createElement(Sidebar)
            )
        );

        const navItems = container.querySelectorAll('a');
        const expectedPaths = %s;

        if (navItems.length !== expectedPaths.length) {
            console.error(`Expected ${expectedPaths.length} nav links, got ${navItems.length}`);
            process.exit(1);
        }

        expectedPaths.forEach((path, index) => {
            const href = navItems[index].getAttribute('href');
            if (href !== path) {
                console.error(`Expected href ${path}, got ${href}`);
                process.exit(1);
            }
        });

        console.log('All nav items rendered successfully');
        """ % json.dumps([item["path"] for item in EXPECTED_NAV_ITEMS])

        result = self._run_node_script(script)
        assert result.returncode == 0, f"Rendering failed: {result.stderr}"

    @pytest.mark.skipif(
        not node_available(),
        reason="Node.js not available for dynamic tests",
    )
    def test_navlink_active_class(self, sidebar_source: str):
        """NavLink must apply active class to the current route."""
        script = """
        const React = require('react');
        const { render } = require('@testing-library/react');
        const { MemoryRouter } = require('react-router-dom');
        const Sidebar = require('./src/components/Sidebar').default;

        const { container } = render(
            React.createElement(MemoryRouter, { initialEntries: ['/analytics'] },
                React.createElement(Sidebar)
            )
        );

        const activeLinks = container.querySelectorAll('a.active');
        if (activeLinks.length !== 1) {
            console.error(`Expected 1 active link, got ${activeLinks.length}`);
            process.exit(1);
        }

        const href = activeLinks[0].getAttribute('href');
        if (href !== '/analytics') {
            console.error(`Expected active link to be /analytics, got ${href}`);
            process.exit(1);
        }

        console.log('Active class applied correctly');
        """

        result = self._run_node_script(script)
        assert result.returncode == 0, f"Active class test failed: {result.stderr}"

    @staticmethod
    def _run_node_script(script: str) -> subprocess.CompletedProcess:
        """Helper to run a Node.js script with proper error handling."""
        try:
            return subprocess.run(
                ["node", "-e", script],
                capture_output=True,
                text=True,
                timeout=30,
                check=False,
                cwd=os.getcwd(),
            )
        except subprocess.TimeoutExpired:
            pytest.fail("Node.js script timed out after 30 seconds")
        except FileNotFoundError:
            pytest.fail("Node.js executable not found")


